def solve(s: str) -> str:
    """
    Reverse the case of each alphabetic character in the string.
    If the string contains no alphabetic characters, return the reversed string.
    """
    # Check if there is at least one alphabetic character
    has_letter = any(ch.isalpha() for ch in s)
    if not has_letter:
        return s[::-1]
    # Otherwise, reverse the case of each alphabetic character
    result = []
    for ch in s:
        if ch.isalpha():
            # swap case
            result.append(ch.swapcase())
        else:
            result.append(ch)
    return ''.join(result)
