def count_up_to(n):
    """
    Return a list of all prime numbers that are strictly less than ``n```.
    If ``n`` is less than 2, the result is an empty list.
    """
    if n <= 2:
        return []

    def is_prime(x):
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True

    primes = []
    for num in range(2, n):
        if is_prime(num):
            primes.append(num)
    return primes
```

