def monotonic(l: list) -> bool:
    """
    Return True if the list elements are monotonically increasing or decreasing.
    """
    if len(l) <= 1:
        return True

    # Determine the direction: positive for increasing, negative for decreasing
    increasing = None
    for i in range(1, len(l)):
        diff = l[i] - l[i - 1]
        if diff == 0:
            continue
        if increasing is None:
            increasing = diff > 0
        else:
            if (diff > 0) != increasing:
                return False
    return True
