def skjkasdkd(lst):
    """
    Return the sum of the digits of the largest prime number in the list.
    If the list contains no prime numbers the function returns 0.
    """
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        if n % 2 == 0:
            return n == 2
        r = int(math.isqrt(n))
        for i in range(3, r + 1, 2):
            if n % i == 0:
                return False
        return True

    largest_prime = None
    for num in lst:
        if is_prime(num):
            if largest_prime is None or num > largest_prime:
                largest_prime = num

    if largest_prime is None:
        return 0

    return sum(int(d) for d in str(largest_prime))
