from typing import List, Tuple

def minPath(grid: List[List[int]], k: int) -> List[int]:
    """
    Find the lexicographically smallest sequence of length k that can be obtained by a path in the grid.
    """
    n = len(grid)
    # Directions: up, down, left, right
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    # dp[l][i][j] will store the best sequence of length l ending at cell (i,j)
    # We only need the previous level to compute the next one
    prev = [[None]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            prev[i][j] = [grid[i][j]]   # length 1

    # helper to compare two sequences lexicographically
    def better(a: List[int], b: List[int]) -> bool:
        """Return True if a is lexicographically smaller than b."""
        for x, y in zip(a, b):
            if x < y:
                return True
            if x > y:
                return False
        return False  # equal

    # iterate for lengths 2..k
    for length in range(2, k+1):
        curr = [[None]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                best_seq: List[int] | None = None
                for di, dj in dirs:
                    ni, nj = i+di, j+dj
                    if 0 <= ni < n and 0 <= nj < n:
                        seq = prev[ni][nj] + [grid[i][j]]
                        if best_seq is None or better(seq, best_seq):
                            best_seq = seq
                curr[i][j] = best_seq
        prev = curr

    # After computing sequences of length k, find the smallest among all cells
    best_overall: List[int] | None = None
    for i in range(n):
        for j in range(n):
            seq = prev[i][j]
            if seq is None:
                continue
            if best_overall is None or better(seq, best_overall):
                best_overall = seq

    return best_overall
